{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Phenylbutyrate, a small aromatic carboxylic acid, showed 78% oral bioavailability in patients, directly supporting F>=20% for a carboxylic acid-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Bumetanide, an ionizable carboxylic acid/sulfonamide drug, had 89% oral bioavailability in normal subjects, supporting high F despite acidic/ionizable character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Suprofen, a propionic acid NSAID, had 92.2% absolute oral bioavailability in healthy subjects, indicating no major first-pass barrier for this acid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Levodopa, a zwitterionic amino acid, showed 80.4% absolute oral bioavailability in healthy volunteers, demonstrating that full ionization does not preclude F>=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "6-MNA, the active carboxylic acid metabolite of nabumetone, had 38% absolute oral bioavailability, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "TP-434, the lowest transferred human oral bioavailability value, was 28%, still above the 20% threshold and therefore not affirmative evidence for low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferred human oral bioavailability measurements for close analogues are at or above 20% (mostly 28-99%), with no affirmative evidence of F<20%. The query's ionization and permeability liabilities introduce uncertainty, but the experimental evidence supports a high prediction.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself.",
    "No transferred analogue with the same dicarboxylic acid/zwitterionic imidazole scaffold; most high-F analogues are monocarboxylic acids.",
    "Several transferred values are near the 20% threshold, so small differences could change classification.",
    "Transporter/efflux and first-pass metabolism data specific to the query are not available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

